COMPILE="$CLANG $TARGET $SYSROOT $DEFINES $INCLUDES $FLAGS"
OBJS_DIR='src/CMakeFiles/dbms.dir/DataTypes/Serializations'

recompile() {
    local name=$1
    echo "=== Recompiling ${name}.cpp ==="
    $COMPILE -o ${OBJS_DIR}/${name}.cpp.o -c /repo/src/DataTypes/Serializations/${name}.cpp
    echo "${name}.cpp.o: OK"
}

recompile SerializationNullable
recompile SerializationVariant
recompile SerializationTuple
recompile SerializationLowCardinality

echo '=== Updating libdbms.a ==='
llvm-ar-21 r src/libdbms.a \
    ${OBJS_DIR}/SerializationNullable.cpp.o \
    ${OBJS_DIR}/SerializationVariant.cpp.o \
    ${OBJS_DIR}/SerializationTuple.cpp.o \
    ${OBJS_DIR}/SerializationLowCardinality.cpp.o
llvm-ranlib-21 src/libdbms.a
echo 'libdbms.a updated: OK'

echo '=== Recompiling Allocator.cpp ==='
ALLOC_OBJ='src/CMakeFiles/clickhouse_common_io.dir/Common/Allocator.cpp.o'
$COMPILE -o ${ALLOC_OBJ} -c /repo/src/Common/Allocator.cpp
echo 'Allocator.cpp.o: OK'

echo '=== Updating libclickhouse_common_io.a ==='
llvm-ar-21 r src/libclickhouse_common_io.a ${ALLOC_OBJ}
llvm-ranlib-21 src/libclickhouse_common_io.a
echo 'libclickhouse_common_io.a updated: OK'
